"LANG2026": {
"s": "Muscle and joint symptoms after top surgery",
"k": "Cross-sectional survey",
"g": "weak",
"t": "surgery",
"pop": "78 Canadian adults who had gender-affirming top surgery, nearly all assigned female at birth.",
"f": "The most common symptoms were altered chest sensation (82%), chest tightness (71%) and shoulder stiffness (56%). Symptoms were most often mild, except changed chest sensation. Only 29% said their symptoms had fully resolved (51% partly), only 28% had sought treatment such as physiotherapy or massage, and fewer than half had been told by clinicians to expect these symptoms. People with symptoms may have been more likely to take part.",
"p": "41699594",
"c": "Lang AE, Fitzgerald SA, Peters MR, et al. Exploring upper limb musculoskeletal symptoms after gender-affirming top surgery: a cross-sectional survey. BMC Musculoskelet Disord. 2026;27(1).",
"d": "10.1186/s12891-026-09622-2",
"y": "2026"
},
"UCSFVAG": {
"s": "Vaginoplasty aftercare (UCSF guidelines)",
"k": "Clinical guideline (sample instructions)",
"g": "",
"t": "surgery",
"pop": "University of California, San Francisco, guidance for primary care clinicians.",
"f": "Sample instructions: avoid strenuous activity for 6 weeks and swimming or cycling for 3 months; no baths for 8 weeks; sitting may be uncomfortable for the first month; swelling settles over 6 to 8 weeks; sex from about 3 months. Dilation starts when the packing is removed, about 3 times a day for the first 3 months, then less often; schedules vary between surgeons. Hair at the surgical site is best cleared beforehand by electrolysis, at least three clearings 8 to 12 weeks apart.",
"c": "UCSF Gender Affirming Health Program. Vaginoplasty procedures, complications and aftercare. In: Guidelines for the primary and gender-affirming care of transgender and gender nonbinary people. San Francisco: University of California; accessed 21 November 2026.",
"u": "https://transcare.ucsf.edu/guidelines/vaginoplasty"
},
